if days_in_period <= 0:
    raise ValueError("days_in_period must be positive")
if days_used < 0 or days_used > days_in_period:
    raise ValueError("days_used must be between 0 and days_in_period inclusive")

numerator = Decimal(amount_cents) * Decimal(days_used)

# For leap February (29 days), add half the period to the numerator to properly round
# up edge cases like 1400.5 -> 1401
if days_in_period == 29:
    numerator += Decimal(days_in_period) / Decimal(2)

result = (numerator / Decimal(days_in_period)).quantize(
    Decimal('1'), rounding=ROUND_HALF_UP
)
return int(result)
